    # Split at the solid separator row or column.
    for r in range(h):
        if len(set(grid[r])) == 1 and r > 0 and h - r - 1 == r:
            panels = (grid[:r], grid[r + 1:])
            break
    if panels is None:
        for c in range(w):
            if all(row[c] == grid[0][c] for row in grid) and c > 0 and w - c - 1 == c:
                panels = ([row[:c] for row in grid], [row[c + 1:] for row in grid])
                break
    if panels is None:
        raise ValueError('No centered solid separator between equal panels')

    first, second = panels
    common = set(v for row in first for v in row) & set(v for row in second for v in row)
    if len(common) != 1:
        raise ValueError(f'Expected one shared panel color, got {common}')
    marker = next(iter(common))
    return [[3 if a == marker and b == marker else marker
             for a, b in zip(row_a, row_b)]
            for row_a, row_b in zip(first, second)]


